import { boolean, index, pgSchema, text, timestamp, uuid } from "drizzle-orm/pg-core";
import { notPersonal, withDataMeta } from "../kernel";

export const identitySchema = pgSchema("identity");

export const persons = withDataMeta(
  identitySchema.table("person", {
    id: uuid("id").primaryKey(),
    email: text("email").notNull().unique(),
    givenName: text("given_name").notNull(),
    familyName: text("family_name").notNull(),
    erpCustomerNumber: text("erp_customer_number").unique(),
    brand: text("brand").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull(),
  }),
  {
    id: notPersonal,
    email: {
      personal: true,
      category: "contact",
      purpose: "Sign-in and account e-mails",
      owner: "identity",
      retention: "account lifetime + 3 years",
    },
    givenName: {
      personal: true,
      category: "identity",
      purpose: "Address the person and fulfil orders",
      owner: "identity",
      retention: "account lifetime + 3 years",
    },
    familyName: {
      personal: true,
      category: "identity",
      purpose: "Address the person and fulfil orders",
      owner: "identity",
      retention: "account lifetime + 3 years",
    },
    erpCustomerNumber: notPersonal,
    brand: notPersonal,
    createdAt: notPersonal,
  },
);

/**
 * Consent records (T3-AC-004). The table is append-only: the application never updates
 * or deletes a row. A new decision inserts a new row; the latest row per person and
 * purpose is the current decision.
 */
export const consents = withDataMeta(
  identitySchema.table(
    "consent",
    {
      id: uuid("id").primaryKey(),
      personId: uuid("person_id")
        .notNull()
        .references(() => persons.id),
      purpose: text("purpose").notNull(),
      textVersion: text("text_version").notNull(),
      channel: text("channel", { enum: ["web", "advisor", "import"] }).notNull(),
      granted: boolean("granted").notNull(),
      decidedAt: timestamp("decided_at", { withTimezone: true }).notNull(),
    },
    (table) => [index("consent_person_purpose_idx").on(table.personId, table.purpose)],
  ),
  {
    id: notPersonal,
    personId: notPersonal,
    purpose: notPersonal,
    textVersion: notPersonal,
    channel: notPersonal,
    granted: {
      personal: true,
      category: "preference",
      purpose: "Prove the consent decision of the person (T3-AC-004)",
      owner: "identity",
      retention: "account lifetime + 3 years",
    },
    decidedAt: notPersonal,
  },
);

