import { type Clock, type EventBus, newId, systemClock } from "../kernel";
import {
  CONSENT_CHANNELS,
  type ConsentChanged,
  type ConsentChannel,
  type ConsentRecord,
  type ConsentRepository,
} from "./consent";
import type { Person, PersonRegistered, PersonRepository } from "./person";

export interface RegisterPersonInput {
  email: string;
  givenName: string;
  familyName: string;
  brand?: string;
}

export interface RecordConsentInput {
  personId: string;
  purpose: string;
  textVersion: string;
  channel: ConsentChannel;
  granted: boolean;
}

export class EmailAlreadyRegisteredError extends Error {
  constructor() {
    super("A person with this e-mail exists");
    this.name = "EmailAlreadyRegisteredError";
  }
}

export class UnknownPersonError extends Error {
  constructor(personId: string) {
    super(`Unknown person: ${personId}`);
    this.name = "UnknownPersonError";
  }
}

export class InvalidConsentError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "InvalidConsentError";
  }
}

export interface IdentityDeps {
  repo: PersonRepository;
  consents: ConsentRepository;
  bus: EventBus;
  clock?: Clock;
}

export function createIdentity({ repo, consents, bus, clock = systemClock }: IdentityDeps) {
  return {
    /** One person record per e-mail address (T3-D-009). */
    async registerPerson(input: RegisterPersonInput): Promise<Person> {
      const email = input.email.trim().toLowerCase();
      if (await repo.findByEmail(email)) throw new EmailAlreadyRegisteredError();
      const now = clock.now();
      const person: Person = {
        id: newId(now),
        email,
        givenName: input.givenName,
        familyName: input.familyName,
        erpCustomerNumber: null,
        brand: input.brand ?? "provital",
        createdAt: now.toISOString(),
      };
      await repo.insert(person);
      const event: PersonRegistered = {
        type: "identity.person-registered",
        id: newId(now),
        occurredAt: now.toISOString(),
        payload: { personId: person.id, brand: person.brand },
      };
      await bus.publish(event);
      return person;
    },

    async getPerson(id: string): Promise<Person | null> {
      return repo.findById(id);
    },

    /**
     * Records a consent decision (T3-AC-004). Every call adds a record; records are never
     * changed or deleted. Publishes `identity.consent-changed`.
     */
    async recordConsent(input: RecordConsentInput): Promise<ConsentRecord> {
      const purpose = input.purpose.trim();
      const textVersion = input.textVersion.trim();
      if (!purpose) throw new InvalidConsentError("A consent needs a purpose");
      if (!textVersion) throw new InvalidConsentError("A consent needs the version of its text");
      if (!CONSENT_CHANNELS.includes(input.channel)) {
        throw new InvalidConsentError(`Unknown consent channel: ${String(input.channel)}`);
      }
      if (!(await repo.findById(input.personId))) throw new UnknownPersonError(input.personId);
      const now = clock.now();
      const record: ConsentRecord = {
        id: newId(now),
        personId: input.personId,
        purpose,
        textVersion,
        channel: input.channel,
        granted: input.granted,
        decidedAt: now.toISOString(),
      };
      await consents.insert(record);
      const event: ConsentChanged = {
        type: "identity.consent-changed",
        id: newId(now),
        occurredAt: now.toISOString(),
        payload: {
          consentId: record.id,
          personId: record.personId,
          purpose: record.purpose,
          textVersion: record.textVersion,
          channel: record.channel,
          granted: record.granted,
          decidedAt: record.decidedAt,
        },
      };
      await bus.publish(event);
      return record;
    },

    /** The latest decision of a person for a purpose, or `null` when there is none. */
    async currentConsent(personId: string, purpose: string): Promise<ConsentRecord | null> {
      return consents.findLatest(personId, purpose.trim());
    },

    /** All consent records of a person, oldest first. */
    async consentHistory(personId: string): Promise<ConsentRecord[]> {
      return consents.listByPerson(personId);
    },
  };
}

export type Identity = ReturnType<typeof createIdentity>;

