import { describe, expect, it } from "vitest";
import { type Clock, InMemoryEventBus } from "../kernel";
import {
  type ConsentChanged,
  createIdentity,
  EmailAlreadyRegisteredError,
  InMemoryConsentRepository,
  InMemoryPersonRepository,
  InvalidConsentError,
  UnknownPersonError,
} from "./index";

/** A clock that advances by one second on every read, so records have distinct times. */
function tickingClock(iso: string): Clock {
  let instant = new Date(iso).getTime();
  return {
    now: () => {
      const now = new Date(instant);
      instant += 1000;
      return now;
    },
  };
}

function setup() {
  const bus = new InMemoryEventBus();
  const identity = createIdentity({
    repo: new InMemoryPersonRepository(),
    consents: new InMemoryConsentRepository(),
    bus,
    clock: tickingClock("2027-01-05T08:00:00Z"),
  });
  return { bus, identity };
}

async function registerErika(identity: ReturnType<typeof setup>["identity"]) {
  return identity.registerPerson({
    email: "erika@example.test",
    givenName: "Erika",
    familyName: "Muster",
  });
}

describe("identity", () => {
  it("T3-AC-003: keeps one person record per e-mail address", async () => {
    const { identity } = setup();
    await identity.registerPerson({
      email: "Erika@Example.test",
      givenName: "Erika",
      familyName: "Muster",
    });
    await expect(
      identity.registerPerson({ email: "erika@example.test", givenName: "E", familyName: "M" }),
    ).rejects.toBeInstanceOf(EmailAlreadyRegisteredError);
  });

  it("publishes identity.person-registered", async () => {
    const { bus, identity } = setup();
    const person = await identity.registerPerson({
      email: "max@example.test",
      givenName: "Max",
      familyName: "Beispiel",
    });
    expect(bus.published).toHaveLength(1);
    expect(bus.published[0]).toMatchObject({
      type: "identity.person-registered",
      payload: { personId: person.id },
    });
  });
});

describe("consents", () => {
  it("T3-AC-004: stores the person, purpose, text version, channel, decision and time", async () => {
    const { identity } = setup();
    const person = await registerErika(identity);
    const record = await identity.recordConsent({
      personId: person.id,
      purpose: "marketing-email",
      textVersion: "2027-01",
      channel: "web",
      granted: true,
    });
    expect(record).toEqual({
      id: expect.any(String),
      personId: person.id,
      purpose: "marketing-email",
      textVersion: "2027-01",
      channel: "web",
      granted: true,
      decidedAt: "2027-01-05T08:00:01.000Z",
    });
    expect(await identity.currentConsent(person.id, "marketing-email")).toEqual(record);
  });

  it("T3-AC-004: a new decision adds a record and never changes an old one", async () => {
    const { identity } = setup();
    const person = await registerErika(identity);
    const given = await identity.recordConsent({
      personId: person.id,
      purpose: "marketing-email",
      textVersion: "2027-01",
      channel: "web",
      granted: true,
    });
    const withdrawn = await identity.recordConsent({
      personId: person.id,
      purpose: "marketing-email",
      textVersion: "2027-01",
      channel: "advisor",
      granted: false,
    });

    expect(withdrawn.id).not.toBe(given.id);
    expect(await identity.currentConsent(person.id, "marketing-email")).toEqual(withdrawn);

    const history = await identity.consentHistory(person.id);
    expect(history).toEqual([given, withdrawn]);
    expect(history[0]).toEqual(given);
    expect(Object.isFrozen(history[0])).toBe(true);
  });

  it("keeps the current decision per purpose", async () => {
    const { identity } = setup();
    const person = await registerErika(identity);
    const marketing = await identity.recordConsent({
      personId: person.id,
      purpose: "marketing-email",
      textVersion: "2027-01",
      channel: "import",
      granted: true,
    });
    const analytics = await identity.recordConsent({
      personId: person.id,
      purpose: "web-analytics",
      textVersion: "2027-01",
      channel: "web",
      granted: false,
    });
    expect(await identity.currentConsent(person.id, "marketing-email")).toEqual(marketing);
    expect(await identity.currentConsent(person.id, "web-analytics")).toEqual(analytics);
    expect(await identity.currentConsent(person.id, "sms")).toBeNull();
  });

  it("returns the history oldest first, only for that person", async () => {
    const { identity } = setup();
    const erika = await registerErika(identity);
    const max = await identity.registerPerson({
      email: "max@example.test",
      givenName: "Max",
      familyName: "Beispiel",
    });
    const first = await identity.recordConsent({
      personId: erika.id,
      purpose: "marketing-email",
      textVersion: "2027-01",
      channel: "web",
      granted: true,
    });
    await identity.recordConsent({
      personId: max.id,
      purpose: "marketing-email",
      textVersion: "2027-01",
      channel: "web",
      granted: true,
    });
    const second = await identity.recordConsent({
      personId: erika.id,
      purpose: "marketing-email",
      textVersion: "2027-02",
      channel: "web",
      granted: true,
    });
    const history = await identity.consentHistory(erika.id);
    expect(history).toEqual([first, second]);
    expect(history[0]?.decidedAt < (history[1]?.decidedAt ?? "")).toBe(true);
    expect(await identity.consentHistory("00000000-0000-7000-8000-000000000000")).toEqual([]);
  });

  it("fails for an unknown person", async () => {
    const { bus, identity } = setup();
    await expect(
      identity.recordConsent({
        personId: "00000000-0000-7000-8000-000000000000",
        purpose: "marketing-email",
        textVersion: "2027-01",
        channel: "web",
        granted: true,
      }),
    ).rejects.toBeInstanceOf(UnknownPersonError);
    expect(bus.published).toHaveLength(0);
  });

  it("rejects an empty purpose, an empty text version and an unknown channel", async () => {
    const { identity } = setup();
    const person = await registerErika(identity);
    const base = { personId: person.id, textVersion: "2027-01", granted: true } as const;
    await expect(
      identity.recordConsent({ ...base, purpose: "  ", channel: "web" }),
    ).rejects.toBeInstanceOf(InvalidConsentError);
    await expect(
      identity.recordConsent({ ...base, purpose: "marketing-email", textVersion: "", channel: "web" }),
    ).rejects.toBeInstanceOf(InvalidConsentError);
    await expect(
      identity.recordConsent({
        ...base,
        purpose: "marketing-email",
        channel: "phone" as unknown as "web",
      }),
    ).rejects.toBeInstanceOf(InvalidConsentError);
    expect(await identity.consentHistory(person.id)).toEqual([]);
  });

  it("publishes identity.consent-changed for every decision", async () => {
    const { bus, identity } = setup();
    const seen: ConsentChanged[] = [];
    bus.subscribe<ConsentChanged>("identity.consent-changed", (event) => {
      seen.push(event);
    });
    const person = await registerErika(identity);
    const given = await identity.recordConsent({
      personId: person.id,
      purpose: "marketing-email",
      textVersion: "2027-01",
      channel: "web",
      granted: true,
    });
    const withdrawn = await identity.recordConsent({
      personId: person.id,
      purpose: "marketing-email",
      textVersion: "2027-01",
      channel: "advisor",
      granted: false,
    });
    expect(seen).toHaveLength(2);
    expect(seen[0]).toMatchObject({
      type: "identity.consent-changed",
      occurredAt: given.decidedAt,
      payload: {
        consentId: given.id,
        personId: person.id,
        purpose: "marketing-email",
        textVersion: "2027-01",
        channel: "web",
        granted: true,
        decidedAt: given.decidedAt,
      },
    });
    expect(seen[1]?.payload).toMatchObject({ consentId: withdrawn.id, granted: false });
  });
});
